  {
    "id": "case-1",
    "prompt": "使用 fde-write 完成：先诊断选题和材料缺口。",
    "must_do": [
      "先诊断选题和材料缺口",
      "支持公众号、小红书、搜索、朋友圈和口播",
      "能生成实际草稿而不只给建议"
    ],
    "must_not": [
      "编造事实",
      "跨项目读取"
    ]
  },
  {
    "id": "case-2",
    "prompt": "继续使用 fde-write 完成：成稿附来源和未核实项。",
    "must_do": [
      "成稿附来源和未核实项",
      "返回来源",
      "说明未确认项"
    ],
    "must_not": [
      "把推断写成事实",
      "覆盖原始材料"
    ]
  },
  {
    "id": "counterexample-1",
    "prompt": "找不到配置，但要求 fde-write 批量写入。",
    "must_do": [
      "停止写入",
      "询问根目录"
    ],
    "must_not": [
      "猜路径",
      "写入用户主目录"
    ]
  }
]

